using System;using System.IO;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;using EanEtikety;
class Revision305Tests {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;static string dir;
 static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,flags).Invoke(o,a);}static T F<T>(object o,string n){return (T)o.GetType().GetField(n,flags).GetValue(o);}static void Check(bool x,string m){checks++;if(!x)throw new Exception(m);}static void Mouse(PreviewPanel p,string n,Point pt){C(p,n,new MouseEventArgs(MouseButtons.Left,1,pt.X,pt.Y,0));}
 static Point Start(PreviewPanel p,int i){p.SelectElement(i);var r=p.ElementRectangle(i);var pt=new Point((int)(r.X+r.Width*.35),(int)(r.Y+r.Height*.5));Mouse(p,"OnMouseDown",pt);Check(p.IsDragging,"drag starts");return pt;}
 static void Near(double a,double b,string m){Check(Math.Abs(a-b)<.000001,m+": "+a+" / "+b);}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var f=new MainForm(Path.Combine(dir,"prefs.xml"))){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();var p=F<PreviewPanel>(f,"preview");var row=F<FlowLayoutPanel>(f,"headerCommands");int icons=0;foreach(Control c in row.Controls){Check(c is HeaderActionButton&&c.Text=="","every toolbar control icon-only");Check(c.Width==c.Height&&c.Width>=36,"square hit target");Check(!string.IsNullOrEmpty(c.AccessibleName),"accessible name");icons++;}Check(icons==18,"18 separate actions including history and tools");Check(typeof(MainForm).GetField("fileMenu",flags)==null,"no duplicate File menu");
 var zoom=F<ContextMenuStrip>(f,"zoomMenu");((ToolStripMenuItem)zoom.Items[3]).PerformClick();Near(p.ViewZoom,1.5,"zoom action");((ToolStripMenuItem)zoom.Items[0]).PerformClick();Near(p.ViewZoom,0,"fit action");
 foreach(int index in new[]{-1,0,-3})foreach(double z in new[]{0d,1,2}){var s=LabelSettings.Default();s.Width=100;s.Height=80;s.Texts[0].X=8;s.Texts[0].Y=8;s.Texts[0].Width=25;s.Texts[0].Height=8;s.BarX=40;s.BarY=35;s.Symbols.Add(new SymbolItem{X=10,Y=55,Width=10,Height=10});C(f,"Apply",s);p.ViewZoom=z;int edits=0,titles=0,ends=0;Action<ElementEdit> onEdit=delegate{edits++;};EventHandler onTitle=delegate{titles++;};Action onEnd=delegate{ends++;};p.ElementEdited+=onEdit;f.TextChanged+=onTitle;p.EditFinished+=onEnd;
 var start=Start(p,index);var original=p.Element(index);var scene=p.Scene;Point last=start;for(int i=0;i<2000;i++){last=new Point(start.X+1+i%73,start.Y+1+i%47);Mouse(p,"OnMouseMove",last);}Check(edits==0,"burst queues latest only");C(p,"FlushDragMove");Check(edits==1,"one frame one edit");Check(object.ReferenceEquals(scene,p.Scene),"frame reuses scene");Check(!F<Timer>(f,"timer").Enabled,"no expensive background rebuild during drag");var moved=p.Element(index).Copy();Mouse(p,"OnMouseUp",last);Near(p.Element(index).X,moved.X,"release keeps final X");Near(p.Element(index).Y,moved.Y,"release keeps final Y");Check(!p.IsDragging&&!F<Timer>(p,"dragFrame").Enabled&&ends==1,"release stops once");Check(titles<=1,"dirty title only once");
 start=Start(p,index);original=p.Element(index).Copy();Mouse(p,"OnMouseMove",new Point(start.X+51,start.Y+27));C(p,"ProcessCmdKey",new Message(),Keys.Escape);C(p,"FlushDragMove");Near(p.Element(index).X,original.X,"Esc drops queued X");Near(p.Element(index).Y,original.Y,"Esc drops queued Y");
 start=Start(p,index);Mouse(p,"OnMouseMove",new Point(start.X+19,start.Y+17));p.Capture=false;Check(!p.IsDragging&&!F<Timer>(p,"dragFrame").Enabled,"capture loss flush and stop");Check(F<SnapResult>(p,"snap")==null,"capture clears guides");p.ElementEdited-=onEdit;f.TextChanged-=onTitle;p.EditFinished-=onEnd;
 }
 // A release returning to the initial pointer must supersede the queued excursion.
 C(f,"Apply",LabelSettings.Default());p.ViewZoom=0;var at=Start(p,-1);var saved=p.Element(-1).Copy();Mouse(p,"OnMouseMove",new Point(at.X+45,at.Y+30));Mouse(p,"OnMouseUp",at);Near(p.Element(-1).X,saved.X,"release at origin X");Near(p.Element(-1).Y,saved.Y,"release at origin Y");
 // Exercise real timer dispatch, not just synthetic frame callbacks.
 at=Start(p,-1);Mouse(p,"OnMouseMove",new Point(at.X+35,at.Y+28));var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<100){Application.DoEvents();System.Threading.Thread.Sleep(1);}Check(!F<bool>(p,"movePending"),"UI timer consumes pending position");Mouse(p,"OnMouseUp",new Point(at.X+35,at.Y+28));C(f,"Apply",LabelSettings.Default());f.Close();}
 File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+checks+" assertions: 15 icon actions, accessibility, zoom; 2000-message bursts for barcode/text/symbol across three zoom levels; cached rendering; title/rebuild throttling; mouse-up, return to origin, Escape, capture loss; real timer dispatch.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
}
